                qh *= Polyfill.UInt64BitsToDouble(sm);
                ql *= Polyfill.UInt64BitsToDouble(sm);

                (qh, ql) = asExpAccurate(-ax, -t, qh, ql);
                rh = th - qh;
                rl = (((th - rh) - qh) - ql) + tl;
            }
        }
        else
        {
            double q0h = t0[j0 * 2 + 1], q0l = t0[j0 * 2 + 0];
            double q1h = t1[j1 * 2 + 1], q1l = t1[j1 * 2 + 0];
            double qh = q0h * q1h, ql = q0h * q1l + q1h * q0l + FusedMultiplyAdd(q0h, q1h, -qh);

            th *= Polyfill.UInt64BitsToDouble(sp);
            tl *= Polyfill.UInt64BitsToDouble(sp);
            qh *= Polyfill.UInt64BitsToDouble(sm);
            ql *= Polyfill.UInt64BitsToDouble(sm);

            double pm = mx * ((ch[0] + mx * ch[1]) + dx2 * (ch[2] + mx * ch[3]));
            double fph = th, fpl = tl + th * pp;
            double fmh = qh, fml = ql + qh * pm;

            rh = fph - fmh;
            rl = ((fph - rh) - fmh) - fml + fpl;
            rh *= CopySign(1.0, x);
            rl *= CopySign(1.0, x);

            double e = 0.33e-18 * rh;
            double lb = rh + (rl - e), ub = rh + (rl + e);
            if (lb == ub)
            {
                return lb;
            }

            (th, tl) = asExpAccurate(ax, t, th, tl);
            (qh, ql) = asExpAccurate(-ax, -t, qh, ql);

            rh = th - qh;
            rl = ((th - rh) - qh) - ql + tl;
        }

        (rh, rl) = fastTwoSum(rh, rl);
        uh = Polyfill.DoubleToUInt64Bits(rh);
        ul = Polyfill.DoubleToUInt64Bits(rl);
        eh = (uh >> 52) & 0x7ff;
        el = (ul >> 52) & 0x7ff;
        ml = (ul + 8) & (~0ul >> 12);

        rh *= CopySign(1.0, x);
        rl *= CopySign(1.0, x);

        rh += rl;
        if (ml <= 16 || eh - el > 103)
        {
            return asSinhDatabase(x, rh);
        }

        return rh;
    }
}
